import{_ as s,o as n,a as p,b as t}from"./app.CttuQoSk.js";const l="/ascendc.github.io/pr/5620/assets/capi_loadunalign.DmNLnF7-.png",c="/ascendc.github.io/pr/5620/assets/capi_storeunalign_1.DWXp4pkA.png",d="/ascendc.github.io/pr/5620/assets/capi_storeunalign_2.Bc_Gk196.png",e="/ascendc.github.io/pr/5620/assets/capi_loadunalign_storeunalign.BWdDFT2_.png",m=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"C API","link":"/api/SIMD-API/c_api/README"},{"text":"Reg矢量计算","link":"/api/SIMD-API/c_api/reg_compute/reg_compute"},{"text":"Reg数据搬入","link":"/api/SIMD-API/c_api/reg_compute/load/load"},{"text":"Reg数据搬入概述","link":"/api/SIMD-API/c_api/reg_compute/load/reg_load_overview"}]},"headers":[],"relativePath":"api/SIMD-API/c_api/reg_compute/load/reg_load_overview.md","filePath":"api/SIMD-API/c_api/reg_compute/load/reg_load_overview.md","outlineHeaders":[{"level":2,"title":"接口分类与选择","slug":"接口分类与选择","link":"#接口分类与选择"},{"level":3,"title":"矢量数据寄存器搬入","slug":"矢量数据寄存器搬入","link":"#矢量数据寄存器搬入"},{"level":4,"title":"对齐搬入","slug":"对齐搬入","link":"#对齐搬入"},{"level":4,"title":"非对齐搬入","slug":"非对齐搬入","link":"#非对齐搬入"},{"level":3,"title":"掩码寄存器搬入","slug":"掩码寄存器搬入","link":"#掩码寄存器搬入"},{"level":2,"title":"通用约束","slug":"通用约束","link":"#通用约束"},{"level":2,"title":"关键特性说明","slug":"关键特性说明","link":"#关键特性说明"},{"level":3,"title":"对齐连续搬入方式对比","slug":"对齐连续搬入方式对比","link":"#对齐连续搬入方式对比"},{"level":4,"title":"连续对齐搬入","slug":"连续对齐搬入","link":"#连续对齐搬入"},{"level":4,"title":"立即数偏移搬入","slug":"立即数偏移搬入","link":"#立即数偏移搬入"},{"level":4,"title":"地址寄存器偏移搬入","slug":"地址寄存器偏移搬入","link":"#地址寄存器偏移搬入"},{"level":4,"title":"Post Update搬入","slug":"Post-Update搬入","link":"#Post-Update搬入"},{"level":3,"title":"非对齐搬运特性","slug":"非对齐搬运特性","link":"#非对齐搬运特性"},{"level":4,"title":"非对齐搬入原理","slug":"非对齐搬入原理","link":"#非对齐搬入原理"},{"level":4,"title":"非对齐搬出原理","slug":"非对齐搬出原理","link":"#非对齐搬出原理"},{"level":4,"title":"非对齐搬入搬出示例","slug":"非对齐搬入搬出示例","link":"#非对齐搬入搬出示例"},{"level":3,"title":"b64数据类型的搬运","slug":"b64数据类型的搬运","link":"#b64数据类型的搬运"}],"lastUpdated":1788916141000}'),o={name:"api/SIMD-API/c_api/reg_compute/load/reg_load_overview.md"};function _(r,a,i,h,g,u){return n(),p("div",null,[...a[0]||(a[0]=[t(`<div><article class="markdown-body"><h1>Reg数据搬入概述</h1><p>Reg数据搬入接口用于将Unified Buffer（UB）中的数据搬入矢量数据寄存器、掩码寄存器或非对齐寄存器。接口均仅在AIV上生效，且需在Vector Function（<code>__simd_vf__</code>标记的函数）内调用。</p><h2 id="接口分类与选择">接口分类与选择<a class="header-anchor" href="#接口分类与选择">​</a></h2><p>根据数据访问方式、搬入后的数据排布以及是否需要自动更新地址，选择相应接口。</p><h3 id="矢量数据寄存器搬入">矢量数据寄存器搬入<a class="header-anchor" href="#矢量数据寄存器搬入">​</a></h3><h4 id="对齐搬入">对齐搬入<a class="header-anchor" href="#对齐搬入">​</a></h4><p><strong>表1</strong> 矢量数据寄存器对齐搬入接口</p><table><thead><tr><th>接口名称</th><th>模式</th><th>功能简述</th><th>地址对齐要求</th></tr></thead><tbody><tr><td><a href="asc_loadalign.html">asc_loadalign</a></td><td>连续对齐搬入</td><td>连续搬入一个VL长度的数据，由用户更新源地址。</td><td>32字节</td></tr><tr><td><a href="asc_loadalign.html">asc_loadalign</a></td><td>立即数偏移搬入模式</td><td>从源起始地址偏移指定距离后搬入一个VL长度的数据。</td><td>32字节</td></tr><tr><td><a href="asc_loadalign.html">asc_loadalign</a></td><td>地址寄存器偏移搬入模式</td><td>按地址寄存器指定的偏移搬入一个VL长度的数据。</td><td>32字节</td></tr><tr><td><a href="asc_loadalign.html">asc_loadalign</a></td><td>非连续对齐搬入模式</td><td>按配置的DataBlock步长非连续搬入8个DataBlock。</td><td>32字节</td></tr><tr><td><a href="asc_loadalign_postupdate.html">asc_loadalign_postupdate</a></td><td>立即数偏移搬入模式</td><td>搬入一个VL长度的数据，并按立即数偏移更新源地址。</td><td>32字节</td></tr><tr><td><a href="asc_loadalign_postupdate.html">asc_loadalign_postupdate</a></td><td>非连续对齐搬入模式</td><td>非连续搬入8个DataBlock，并自动更新源地址。</td><td>32字节</td></tr><tr><td><a href="asc_loadalign_datablock_strided.html">asc_loadalign_datablock_strided</a></td><td>非连续对齐搬入模式</td><td>按配置的DataBlock步长非连续搬入8个DataBlock，通过返回值返回结果。</td><td>32字节</td></tr><tr><td><a href="asc_loadalign_brc_datablock.html">asc_loadalign_brc_datablock</a></td><td>对齐搬入模式</td><td>将一个DataBlock广播到整个矢量数据寄存器。</td><td>32字节</td></tr><tr><td><a href="asc_loadalign_brc_datablock.html">asc_loadalign_brc_datablock</a></td><td>立即数偏移搬入模式</td><td>从立即数偏移位置读取一个DataBlock并广播。</td><td>32字节</td></tr><tr><td><a href="asc_loadalign_brc_datablock.html">asc_loadalign_brc_datablock</a></td><td>地址寄存器偏移搬入模式</td><td>从地址寄存器偏移位置读取一个DataBlock并广播。</td><td>32字节</td></tr><tr><td><a href="asc_loadalign_brc_datablock_postupdate.html">asc_loadalign_brc_datablock_postupdate</a></td><td>Post Update搬入模式</td><td>将一个DataBlock广播到整个矢量数据寄存器，并自动更新源地址。</td><td>32字节</td></tr><tr><td><a href="asc_loadalign_brc_elem.html">asc_loadalign_brc_elem</a></td><td>对齐搬入模式</td><td>将一个元素广播到整个矢量数据寄存器。</td><td>按dtype对齐</td></tr><tr><td><a href="asc_loadalign_brc_elem.html">asc_loadalign_brc_elem</a></td><td>立即数偏移搬入模式</td><td>从立即数偏移位置读取一个元素并广播。</td><td>按dtype对齐</td></tr><tr><td><a href="asc_loadalign_brc_elem.html">asc_loadalign_brc_elem</a></td><td>地址寄存器偏移搬入模式</td><td>从地址寄存器偏移位置读取一个元素并广播。</td><td>按dtype对齐</td></tr><tr><td><a href="asc_loadalign_brc_elem_postupdate.html">asc_loadalign_brc_elem_postupdate</a></td><td>Post Update搬入模式</td><td>将一个元素广播到整个矢量数据寄存器，并自动更新源地址。</td><td>按dtype对齐</td></tr><tr><td><a href="asc_loadalign_brc_elem2datablock.html">asc_loadalign_brc_elem2datablock</a></td><td>对齐搬入模式</td><td>连续读取8个元素，并将每个元素广播到一个DataBlock。</td><td>b16为16字节，b32为32字节</td></tr><tr><td><a href="asc_loadalign_brc_elem2datablock.html">asc_loadalign_brc_elem2datablock</a></td><td>立即数偏移搬入模式</td><td>从立即数偏移位置读取8个元素，并分别广播到一个DataBlock。</td><td>b16为16字节，b32为32字节</td></tr><tr><td><a href="asc_loadalign_brc_elem2datablock.html">asc_loadalign_brc_elem2datablock</a></td><td>地址寄存器偏移搬入模式</td><td>从地址寄存器偏移位置读取8个元素，并分别广播到一个DataBlock。</td><td>b16为16字节，b32为32字节</td></tr><tr><td><a href="asc_loadalign_brc_elem2datablock_postupdate.html">asc_loadalign_brc_elem2datablock_postupdate</a></td><td>Post Update搬入模式</td><td>连续读取并广播8个元素，并自动更新源地址。</td><td>b16为16字节，b32为32字节</td></tr><tr><td><a href="asc_loadalign_deintlv.html">asc_loadalign_deintlv</a></td><td>对齐搬入模式</td><td>读取2×VL长度的数据，解交织后写入两个矢量数据寄存器。</td><td>32字节</td></tr><tr><td><a href="asc_loadalign_deintlv.html">asc_loadalign_deintlv</a></td><td>立即数偏移搬入模式</td><td>从立即数偏移位置读取数据并解交织。</td><td>32字节</td></tr><tr><td><a href="asc_loadalign_deintlv.html">asc_loadalign_deintlv</a></td><td>地址寄存器偏移搬入模式</td><td>从地址寄存器偏移位置读取数据并解交织。</td><td>32字节</td></tr><tr><td><a href="asc_loadalign_deintlv_postupdate.html">asc_loadalign_deintlv_postupdate</a></td><td>Post Update搬入模式</td><td>读取数据并解交织到两个矢量数据寄存器，同时自动更新源地址。</td><td>32字节</td></tr><tr><td><a href="asc_loadalign_downsample.html">asc_loadalign_downsample</a></td><td>对齐搬入模式</td><td>读取2×VL长度的数据，保留偶数下标元素。</td><td>32字节</td></tr><tr><td><a href="asc_loadalign_downsample.html">asc_loadalign_downsample</a></td><td>立即数偏移搬入模式</td><td>从立即数偏移位置读取数据并进行2倍下采样。</td><td>32字节</td></tr><tr><td><a href="asc_loadalign_downsample.html">asc_loadalign_downsample</a></td><td>地址寄存器偏移搬入模式</td><td>从地址寄存器偏移位置读取数据并进行2倍下采样。</td><td>32字节</td></tr><tr><td><a href="asc_loadalign_downsample_postupdate.html">asc_loadalign_downsample_postupdate</a></td><td>Post Update搬入模式</td><td>读取数据并进行2倍下采样，同时自动更新源地址。</td><td>32字节</td></tr><tr><td><a href="asc_loadalign_upsample.html">asc_loadalign_upsample</a></td><td>对齐搬入模式</td><td>读取VL/2长度的数据，将每个元素重复两次。</td><td>32字节</td></tr><tr><td><a href="asc_loadalign_upsample.html">asc_loadalign_upsample</a></td><td>立即数偏移搬入模式</td><td>从立即数偏移位置读取数据并进行2倍上采样。</td><td>32字节</td></tr><tr><td><a href="asc_loadalign_upsample.html">asc_loadalign_upsample</a></td><td>地址寄存器偏移搬入模式</td><td>从地址寄存器偏移位置读取数据并进行2倍上采样。</td><td>32字节</td></tr><tr><td><a href="asc_loadalign_upsample_postupdate.html">asc_loadalign_upsample_postupdate</a></td><td>Post Update搬入模式</td><td>读取数据并进行2倍上采样，同时自动更新源地址。</td><td>32字节</td></tr><tr><td><a href="asc_loadalign_unpack.html">asc_loadalign_unpack</a></td><td>对齐搬入模式</td><td>读取VL/2长度的数据，在每个源元素后补1个0。</td><td>32字节</td></tr><tr><td><a href="asc_loadalign_unpack.html">asc_loadalign_unpack</a></td><td>立即数偏移搬入模式</td><td>从立即数偏移位置读取数据，在每个源元素后补1个0。</td><td>32字节</td></tr><tr><td><a href="asc_loadalign_unpack.html">asc_loadalign_unpack</a></td><td>地址寄存器偏移搬入模式</td><td>从地址寄存器偏移位置读取数据，在每个源元素后补1个0。</td><td>32字节</td></tr><tr><td><a href="asc_loadalign_unpack_postupdate.html">asc_loadalign_unpack_postupdate</a></td><td>Post Update搬入模式</td><td>读取VL/2长度的数据，在每个源元素后补1个0，并自动更新源地址。</td><td>32字节</td></tr><tr><td><a href="asc_loadalign_unpack4.html">asc_loadalign_unpack4</a></td><td>对齐搬入模式</td><td>读取VL/4长度的数据，在每个源元素后补3个0。</td><td>32字节</td></tr><tr><td><a href="asc_loadalign_unpack4.html">asc_loadalign_unpack4</a></td><td>立即数偏移搬入模式</td><td>从立即数偏移位置读取数据，在每个源元素后补3个0。</td><td>32字节</td></tr><tr><td><a href="asc_loadalign_unpack4.html">asc_loadalign_unpack4</a></td><td>地址寄存器偏移搬入模式</td><td>从地址寄存器偏移位置读取数据，在每个源元素后补3个0。</td><td>32字节</td></tr><tr><td><a href="asc_loadalign_unpack4_postupdate.html">asc_loadalign_unpack4_postupdate</a></td><td>Post Update搬入模式</td><td>读取VL/4长度的数据，在每个源元素后补3个0，并自动更新源地址。</td><td>32字节</td></tr></tbody></table><h4 id="非对齐搬入">非对齐搬入<a class="header-anchor" href="#非对齐搬入">​</a></h4><p><strong>表2</strong> 矢量数据寄存器非对齐搬入接口</p><table><thead><tr><th>接口名称</th><th>模式</th><th>功能简述</th><th>地址对齐要求</th></tr></thead><tbody><tr><td><a href="asc_load.html">asc_load</a></td><td>连续非对齐搬入模式</td><td>搬入一个VL长度的数据，由用户更新源地址。该接口为易用性接口。</td><td>按dtype对齐</td></tr><tr><td><a href="asc_loadunalign_pre.html">asc_loadunalign_pre</a></td><td>源地址预处理模式</td><td>根据源地址初始化非对齐寄存器。</td><td>按dtype对齐</td></tr><tr><td><a href="asc_loadunalign_pre.html">asc_loadunalign_pre</a></td><td>地址寄存器偏移预处理模式</td><td>根据源地址和地址寄存器偏移初始化非对齐寄存器。</td><td>按dtype对齐</td></tr><tr><td><a href="asc_loadunalign.html">asc_loadunalign</a></td><td>连续非对齐搬入模式</td><td>使用预处理结果搬入一个VL长度的数据，由用户更新源地址。</td><td>按dtype对齐</td></tr><tr><td><a href="asc_loadunalign_postupdate.html">asc_loadunalign_postupdate</a></td><td>连续非对齐搬入模式</td><td>使用预处理结果搬入指定数量的元素，并自动更新源地址和非对齐寄存器。</td><td>按dtype对齐</td></tr><tr><td><a href="asc_loadunalign_postupdate.html">asc_loadunalign_postupdate</a></td><td>地址寄存器偏移搬入模式</td><td>从地址寄存器偏移位置搬入数据，并自动更新偏移和非对齐寄存器。</td><td>按dtype对齐</td></tr></tbody></table><p><code>asc_load</code>为易用性接口。对性能有要求的连续非对齐搬入场景，可使用<code>asc_loadunalign</code>或<code>asc_loadunalign_postupdate</code>。</p><h3 id="掩码寄存器搬入">掩码寄存器搬入<a class="header-anchor" href="#掩码寄存器搬入">​</a></h3><p><strong>表3</strong> 掩码寄存器搬入接口</p><table><thead><tr><th>接口名称</th><th>模式</th><th>功能简述</th><th>地址对齐要求</th></tr></thead><tbody><tr><td><a href="asc_loadalign.html">asc_loadalign</a></td><td>连续对齐搬入</td><td>连续搬入VL/8长度的数据，由用户更新源地址。</td><td>32字节</td></tr><tr><td><a href="asc_loadalign.html">asc_loadalign</a></td><td>立即数偏移搬入模式</td><td>从源起始地址偏移指定距离后搬入VL/8长度的数据。</td><td>32字节</td></tr><tr><td><a href="asc_loadalign.html">asc_loadalign</a></td><td>地址寄存器偏移搬入模式</td><td>按地址寄存器指定的偏移搬入VL/8长度的数据。</td><td>32字节</td></tr><tr><td><a href="asc_loadalign_postupdate.html">asc_loadalign_postupdate</a></td><td>立即数偏移搬入模式</td><td>搬入VL/8长度的数据，并按立即数偏移更新源地址。</td><td>32字节</td></tr><tr><td><a href="asc_loadalign_mask.html">asc_loadalign_mask</a></td><td>连续对齐搬入</td><td>连续搬入VL/8长度的数据，通过返回值返回结果。</td><td>32字节</td></tr><tr><td><a href="asc_loadalign_downsample.html">asc_loadalign_downsample</a></td><td>对齐搬入模式</td><td>读取VL/4长度的数据，保留偶数下标bit。</td><td>32字节</td></tr><tr><td><a href="asc_loadalign_downsample.html">asc_loadalign_downsample</a></td><td>立即数偏移搬入模式</td><td>从立即数偏移位置读取数据并进行2倍下采样。</td><td>32字节</td></tr><tr><td><a href="asc_loadalign_downsample.html">asc_loadalign_downsample</a></td><td>地址寄存器偏移搬入模式</td><td>从地址寄存器偏移位置读取数据并进行2倍下采样。</td><td>32字节</td></tr><tr><td><a href="asc_loadalign_downsample_postupdate.html">asc_loadalign_downsample_postupdate</a></td><td>Post Update搬入模式</td><td>读取数据并进行2倍下采样，同时自动更新源地址。</td><td>32字节</td></tr><tr><td><a href="asc_loadalign_mask_downsample.html">asc_loadalign_mask_downsample</a></td><td>对齐搬入模式</td><td>读取VL/4长度的数据，保留偶数下标bit，通过返回值返回结果。</td><td>32字节</td></tr><tr><td><a href="asc_loadalign_upsample.html">asc_loadalign_upsample</a></td><td>对齐搬入模式</td><td>读取VL/16长度的数据，将每个bit重复两次。</td><td>16字节</td></tr><tr><td><a href="asc_loadalign_upsample.html">asc_loadalign_upsample</a></td><td>立即数偏移搬入模式</td><td>从立即数偏移位置读取数据并进行2倍上采样。</td><td>16字节</td></tr><tr><td><a href="asc_loadalign_upsample.html">asc_loadalign_upsample</a></td><td>地址寄存器偏移搬入模式</td><td>从地址寄存器偏移位置读取数据并进行2倍上采样。</td><td>16字节</td></tr><tr><td><a href="asc_loadalign_upsample_postupdate.html">asc_loadalign_upsample_postupdate</a></td><td>Post Update搬入模式</td><td>读取数据并进行2倍上采样，同时自动更新源地址。</td><td>16字节</td></tr><tr><td><a href="asc_loadalign_mask_upsample.html">asc_loadalign_mask_upsample</a></td><td>对齐搬入模式</td><td>读取VL/16长度的数据，将每个bit重复两次，通过返回值返回结果。</td><td>16字节</td></tr></tbody></table><h2 id="通用约束">通用约束<a class="header-anchor" href="#通用约束">​</a></h2><ul><li>本接口仅在AIV上生效，非AIV调用直接返回。</li><li>本接口在Vector Function（<code>__simd_vf__</code>标记的函数）内调用。</li><li>各功能模式下的实际读取地址必须满足<a href="#%E6%8E%A5%E5%8F%A3%E5%88%86%E7%B1%BB%E4%B8%8E%E9%80%89%E6%8B%A9">接口分类与选择</a>中的地址对齐要求，且实际读取范围必须在UB地址空间内且不越界，否则会报错。</li><li>UB容量上限为256KB，用户可用容量随编译选项与编程场景变化。UB地址偏移后不可超过实际可用容量，否则会报错。详细说明请参见<a href="../../general_description_and_constraints.html#%E5%AD%98%E5%82%A8%E5%8D%95%E5%85%83%E8%AF%B4%E6%98%8E">存储单元说明</a>。</li><li>如果本指令与其他指令存在UB地址重叠，需要插入同步指令<a href="../reg_sync/asc_mem_bar.html">asc_mem_bar</a>，保证多个指令串行化，防止出现异常数据。</li></ul><h2 id="关键特性说明">关键特性说明<a class="header-anchor" href="#关键特性说明">​</a></h2><h3 id="对齐连续搬入方式对比">对齐连续搬入方式对比<a class="header-anchor" href="#对齐连续搬入方式对比">​</a></h3><p>对齐连续搬入提供四种源地址维护方式。以下示例均将长度为1024、数据类型为<code>half</code>的源数据连续搬入矢量数据寄存器，再写入UB。单次迭代处理128个元素，共迭代8次，最终结果均为<code>dst[i] = src[i]</code>。</p><p><strong>表4</strong> 对齐连续搬入方式对比</p><table><thead><tr><th>场景</th><th>搬入方式</th><th>源地址维护方式</th><th>适用场景</th></tr></thead><tbody><tr><td>场景1</td><td>连续对齐搬入</td><td>调用方通过指针运算计算每次搬入的源地址。</td><td>源地址偏移规则简单，且需要由用户显式控制地址。</td></tr><tr><td>场景2</td><td>立即数偏移搬入</td><td>将相对源基地址的元素偏移作为<code>int32_t</code>参数传入，接口不修改源地址指针。</td><td>需要保留源基地址，并通过普通整数指定偏移。</td></tr><tr><td>场景3</td><td>地址寄存器偏移搬入</td><td>通过<a href="../reg_addr_reg/asc_update_addr_reg.html">asc_update_addr_reg</a>生成<code>addr_reg</code>，由硬件在迭代中更新偏移。</td><td>Hardware Loop内偏移随迭代变化。</td></tr><tr><td>场景4</td><td>Post Update搬入</td><td><code>asc_loadalign_postupdate</code>在每次搬入后自动更新源地址指针。</td><td>连续搬入且无需用户手动维护源地址。</td></tr></tbody></table><h4 id="连续对齐搬入">连续对齐搬入<a class="header-anchor" href="#连续对齐搬入">​</a></h4><p>调用<code>asc_loadalign</code>的连续对齐搬入形式。源地址通过<code>src + i * one_repeat_size</code>计算，<code>one_repeat_size</code>为128个<code>half</code>元素。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__simd_vf__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">load_align_continuous_vf</span><span class="p">(</span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">half</span><span class="o">*</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">half</span><span class="o">*</span><span class="w"> </span><span class="n">src</span><span class="p">,</span>
<span class="w">                                                 </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">one_repeat_size</span><span class="p">,</span><span class="w"> </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">repeat_times</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="n">vector_half</span><span class="w"> </span><span class="n">data_reg</span><span class="p">;</span>
<span class="w">    </span><span class="n">vector_bool</span><span class="w"> </span><span class="n">mask</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc_create_mask_b16</span><span class="p">(</span><span class="n">PAT_ALL</span><span class="p">);</span>
<span class="w">    </span><span class="k">for</span><span class="w"> </span><span class="p">(</span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">repeat_times</span><span class="p">;</span><span class="w"> </span><span class="o">++</span><span class="n">i</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="n">asc_loadalign</span><span class="p">(</span><span class="n">data_reg</span><span class="p">,</span><span class="w"> </span><span class="n">src</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">one_repeat_size</span><span class="p">);</span>
<span class="w">        </span><span class="n">asc_storealign</span><span class="p">(</span><span class="n">dst</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">one_repeat_size</span><span class="p">,</span><span class="w"> </span><span class="n">data_reg</span><span class="p">,</span><span class="w"> </span><span class="n">mask</span><span class="p">);</span>
<span class="w">    </span><span class="p">}</span>
<span class="p">}</span>
</code></pre></div><h4 id="立即数偏移搬入">立即数偏移搬入<a class="header-anchor" href="#立即数偏移搬入">​</a></h4><p>调用<code>asc_loadalign</code>的立即数偏移搬入模式。<code>offset</code>相对<code>src</code>基地址，单位为元素；本示例通过<code>i * one_repeat_size</code>计算每次搬入的偏移。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__simd_vf__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">load_align_immediate_offset_vf</span><span class="p">(</span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">half</span><span class="o">*</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">half</span><span class="o">*</span><span class="w"> </span><span class="n">src</span><span class="p">,</span>
<span class="w">                                                       </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">one_repeat_size</span><span class="p">,</span><span class="w"> </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">repeat_times</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="n">vector_half</span><span class="w"> </span><span class="n">data_reg</span><span class="p">;</span>
<span class="w">    </span><span class="n">vector_bool</span><span class="w"> </span><span class="n">mask</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc_create_mask_b16</span><span class="p">(</span><span class="n">PAT_ALL</span><span class="p">);</span>
<span class="w">    </span><span class="k">for</span><span class="w"> </span><span class="p">(</span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">repeat_times</span><span class="p">;</span><span class="w"> </span><span class="o">++</span><span class="n">i</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="n">asc_loadalign</span><span class="p">(</span><span class="n">data_reg</span><span class="p">,</span><span class="w"> </span><span class="n">src</span><span class="p">,</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">one_repeat_size</span><span class="p">);</span>
<span class="w">        </span><span class="n">asc_storealign</span><span class="p">(</span><span class="n">dst</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">one_repeat_size</span><span class="p">,</span><span class="w"> </span><span class="n">data_reg</span><span class="p">,</span><span class="w"> </span><span class="n">mask</span><span class="p">);</span>
<span class="w">    </span><span class="p">}</span>
<span class="p">}</span>
</code></pre></div><h4 id="地址寄存器偏移搬入">地址寄存器偏移搬入<a class="header-anchor" href="#地址寄存器偏移搬入">​</a></h4><p>调用<code>asc_loadalign</code>的地址寄存器偏移搬入模式。<code>addr_reg</code>须在最内层循环中赋值并使用，b16模式下偏移单位为元素。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__simd_vf__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">load_align_addr_reg_offset_vf</span><span class="p">(</span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">half</span><span class="o">*</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">half</span><span class="o">*</span><span class="w"> </span><span class="n">src</span><span class="p">,</span>
<span class="w">                                                      </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">one_repeat_size</span><span class="p">,</span><span class="w"> </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">repeat_times</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="n">vector_half</span><span class="w"> </span><span class="n">data_reg</span><span class="p">;</span>
<span class="w">    </span><span class="n">vector_bool</span><span class="w"> </span><span class="n">mask</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc_create_mask_b16</span><span class="p">(</span><span class="n">PAT_ALL</span><span class="p">);</span>
<span class="w">    </span><span class="n">addr_reg</span><span class="w"> </span><span class="n">offset</span><span class="p">;</span>
<span class="w">    </span><span class="k">for</span><span class="w"> </span><span class="p">(</span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">repeat_times</span><span class="p">;</span><span class="w"> </span><span class="o">++</span><span class="n">i</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="n">offset</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc_update_addr_reg_b16</span><span class="p">(</span><span class="n">one_repeat_size</span><span class="p">);</span>
<span class="w">        </span><span class="n">asc_loadalign</span><span class="p">(</span><span class="n">data_reg</span><span class="p">,</span><span class="w"> </span><span class="n">src</span><span class="p">,</span><span class="w"> </span><span class="n">offset</span><span class="p">);</span>
<span class="w">        </span><span class="n">asc_storealign</span><span class="p">(</span><span class="n">dst</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">one_repeat_size</span><span class="p">,</span><span class="w"> </span><span class="n">data_reg</span><span class="p">,</span><span class="w"> </span><span class="n">mask</span><span class="p">);</span>
<span class="w">    </span><span class="p">}</span>
<span class="p">}</span>
</code></pre></div><h4 id="Post-Update搬入">Post Update搬入<a class="header-anchor" href="#Post-Update搬入">​</a></h4><p>调用<code>asc_loadalign_postupdate</code>的立即数偏移搬入模式。源地址以引用方式传入，接口在每次搬入后将其向后更新<code>one_repeat_size</code>个元素。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__simd_vf__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">load_align_post_update_vf</span><span class="p">(</span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">half</span><span class="o">*</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">half</span><span class="o">*</span><span class="w"> </span><span class="n">src</span><span class="p">,</span>
<span class="w">                                                  </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">one_repeat_size</span><span class="p">,</span><span class="w"> </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">repeat_times</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="n">vector_half</span><span class="w"> </span><span class="n">data_reg</span><span class="p">;</span>
<span class="w">    </span><span class="n">vector_bool</span><span class="w"> </span><span class="n">mask</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc_create_mask_b16</span><span class="p">(</span><span class="n">PAT_ALL</span><span class="p">);</span>
<span class="w">    </span><span class="k">for</span><span class="w"> </span><span class="p">(</span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">repeat_times</span><span class="p">;</span><span class="w"> </span><span class="o">++</span><span class="n">i</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="n">asc_loadalign_postupdate</span><span class="p">(</span><span class="n">data_reg</span><span class="p">,</span><span class="w"> </span><span class="n">src</span><span class="p">,</span><span class="w"> </span><span class="n">one_repeat_size</span><span class="p">);</span>
<span class="w">        </span><span class="n">asc_storealign</span><span class="p">(</span><span class="n">dst</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">one_repeat_size</span><span class="p">,</span><span class="w"> </span><span class="n">data_reg</span><span class="p">,</span><span class="w"> </span><span class="n">mask</span><span class="p">);</span>
<span class="w">    </span><span class="p">}</span>
<span class="p">}</span>
</code></pre></div><h3 id="非对齐搬运特性">非对齐搬运特性<a class="header-anchor" href="#非对齐搬运特性">​</a></h3><p>非对齐搬运用于有效起始地址满足dtype对齐、但不满足32字节对齐的连续数据搬入或搬出场景。搬入和搬出均通过<a href="../../defs/type/data_type_definition.html#%E9%9D%9E%E5%AF%B9%E9%BD%90%E5%AF%84%E5%AD%98%E5%99%A8">非对齐寄存器</a>保存跨32字节边界的数据，以保证连续数据的完整性。</p><h4 id="非对齐搬入原理">非对齐搬入原理<a class="header-anchor" href="#非对齐搬入原理">​</a></h4><p>非对齐搬入通过非对齐寄存器缓存起始地址所在32字节块的前置数据，再与后续读取的数据拼接，得到从有效起始地址开始的VL长度数据。</p><p><strong>图1</strong> 非对齐搬入示意图<a id="fig-loadunalign"></a></p><p><img src="`+l+'" alt="非对齐搬入示意图" title="非对齐搬入示意图"></p><p>设有效起始字节地址为<code>src_start_addr</code>，将其向低地址方向按32字节对齐，得到<code>aligned_src_start_addr</code>。处理过程如下：</p><ol><li>调用<a href="asc_loadunalign_pre.html">asc_loadunalign_pre</a>，将<code>[aligned_src_start_addr, aligned_src_start_addr + 32)</code>范围内的数据缓存至非对齐寄存器。</li><li>调用<a href="asc_loadunalign.html">asc_loadunalign</a>或<a href="asc_loadunalign_postupdate.html">asc_loadunalign_postupdate</a>，将前置缓存与后续读取数据拼接，得到<code>[src_start_addr, src_start_addr + VL)</code>范围的数据并写入矢量数据寄存器。<code>asc_loadunalign_postupdate</code>还会更新非对齐寄存器，以缓存下一次连续搬入所需的前置数据。</li></ol><p>实际访问会覆盖向低地址方向对齐后的32字节范围，因此除有效起始地址满足dtype对齐外，对齐后的读取范围也必须位于UB地址空间内。</p><p><strong>表5</strong> 非对齐搬入接口的配合关系</p><table><thead><tr><th>主搬入方式</th><th>配套接口</th><th>说明</th></tr></thead><tbody><tr><td><a href="asc_loadunalign.html">asc_loadunalign</a></td><td><a href="asc_loadunalign_pre.html">asc_loadunalign_pre</a></td><td>用户手动更新源地址。每次搬入前均需调用预处理接口，且两个接口必须使用相同的源地址。</td></tr><tr><td><a href="asc_loadunalign_postupdate.html">asc_loadunalign_postupdate</a>的立即数偏移模式</td><td><a href="asc_loadunalign_pre.html">asc_loadunalign_pre</a></td><td>接口自动更新源地址。首次搬入前调用预处理接口；后续连续搬入可复用更新后的非对齐寄存器，源地址被另行修改后必须重新预处理。</td></tr><tr><td><a href="asc_loadunalign_postupdate.html">asc_loadunalign_postupdate</a>的地址寄存器偏移模式</td><td><a href="../reg_addr_reg/asc_update_addr_reg.html">asc_update_addr_reg</a>、<a href="asc_loadunalign_pre.html">asc_loadunalign_pre</a></td><td>接口自动更新地址寄存器偏移。每次循环迭代先生成起始偏移，再使用相同的源地址和偏移进行预处理；迭代内连续搬入可复用更新后的非对齐寄存器，源地址或偏移被另行修改后必须重新预处理。</td></tr></tbody></table><h4 id="非对齐搬出原理">非对齐搬出原理<a class="header-anchor" href="#非对齐搬出原理">​</a></h4><p>非对齐搬出将矢量数据寄存器中的连续数据写入非32字节对齐的UB地址。每次主搬出会将可以直接写入的主块写入UB，并将末尾不能构成32字节对齐块的数据保存在非对齐寄存器。后续连续搬出时，接口将该尾块与本次主块的起始数据拼接后写入UB，并更新本次尾块。</p><p>首次搬出前，非对齐寄存器无需初始化。连续调用时，必须复用同一个非对齐寄存器；若上一次尾块与本次主块不连续，则需要在下一次主搬出前调用后处理接口完成前一次尾块的写入。</p><p><strong>图2</strong> 非对齐搬出示意图（首次搬出）<a id="fig-storeunalign-empty"></a></p><p><img src="'+c+'" alt="非对齐搬出示意图（首次搬出）" title="非对齐搬出示意图（首次搬出）"></p><p>首次搬出时，非对齐寄存器中没有前序尾块数据。主搬出接口将矢量数据寄存器中可直接写入的数据写入UB，并将末尾数据保存至非对齐寄存器。调用后处理接口后，尾块数据被写入UB。</p><p><strong>图3</strong> 非对齐搬出示意图（连续搬出）<a id="fig-storeunalign-cached"></a></p><p><img src="'+d+'" alt="非对齐搬出示意图（连续搬出）" title="非对齐搬出示意图（连续搬出）"></p><p>后续连续搬出时，主搬出接口将非对齐寄存器中的前序尾块与本次矢量数据寄存器的主块数据拼接后写入UB，再将本次尾块更新至非对齐寄存器。连续搬出结束后，调用后处理接口写入最后一次缓存的尾块。</p><p><strong>表6</strong> 非对齐搬出接口的配合关系</p><table><thead><tr><th>主搬出方式</th><th>配套接口</th><th>说明</th></tr></thead><tbody><tr><td><a href="../store/asc_storeunalign.html">asc_storeunalign</a></td><td><a href="../store/asc_storeunalign_post.html">asc_storeunalign_post</a></td><td>用户手动更新目的地址。</td></tr><tr><td><a href="../store/asc_storeunalign_postupdate.html">asc_storeunalign_postupdate</a>的立即数偏移模式</td><td><a href="../store/asc_storeunalign_post_postupdate.html">asc_storeunalign_post_postupdate</a></td><td>接口自动更新目的地址。</td></tr><tr><td><a href="../store/asc_storeunalign_postupdate.html">asc_storeunalign_postupdate</a>的地址寄存器偏移模式</td><td><a href="../store/asc_storeunalign_post.html">asc_storeunalign_post</a></td><td>主搬出和后处理接口需复用同一个非对齐寄存器及地址寄存器。</td></tr></tbody></table><h4 id="非对齐搬入搬出示例">非对齐搬入搬出示例<a class="header-anchor" href="#非对齐搬入搬出示例">​</a></h4><p>下图以<code>uint32_t</code>数据为例，展示连续非对齐搬入后再连续非对齐搬出的过程。搬入前置初始化和搬出后处理均位于循环外：连续搬入时，<code>asc_loadunalign_postupdate</code>更新的非对齐寄存器可供下一次搬入使用；连续搬出时，<code>asc_storeunalign_postupdate</code>将尾块保存在非对齐寄存器，最后一次循环结束后再统一写回。</p><p><strong>图4</strong> 连续非对齐搬入搬出示例<a id="fig-loadstoreunalign"></a></p><p><img src="'+e+`" alt="连续非对齐搬入搬出示例" title="连续非对齐搬入搬出示例"></p><div class="code-block"><div class="code-header"><span class="lang-label">C</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__simd_vf__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">load_store_unalign_vf</span><span class="p">(</span><span class="n">__ubuf__</span><span class="w"> </span><span class="kt">uint32_t</span><span class="o">*</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="n">__ubuf__</span><span class="w"> </span><span class="kt">uint32_t</span><span class="o">*</span><span class="w"> </span><span class="n">src</span><span class="p">,</span>
<span class="w">                                              </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">count</span><span class="p">,</span><span class="w"> </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">repeat_times</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="n">vector_load_unalign</span><span class="w"> </span><span class="n">ureg0</span><span class="p">;</span>
<span class="w">    </span><span class="n">vector_store_unalign</span><span class="w"> </span><span class="n">ureg1</span><span class="p">;</span>
<span class="w">    </span><span class="n">vector_uint32_t</span><span class="w"> </span><span class="n">data_reg</span><span class="p">;</span>
<span class="w">    </span><span class="c1">// 非对齐搬入初始化，只需在循环开始前调用一次。</span>
<span class="w">    </span><span class="n">asc_loadunalign_pre</span><span class="p">(</span><span class="n">ureg0</span><span class="p">,</span><span class="w"> </span><span class="n">src</span><span class="p">);</span>
<span class="w">    </span><span class="k">for</span><span class="w"> </span><span class="p">(</span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">repeat_times</span><span class="p">;</span><span class="w"> </span><span class="o">++</span><span class="n">i</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="n">asc_loadunalign_postupdate</span><span class="p">(</span><span class="n">data_reg</span><span class="p">,</span><span class="w"> </span><span class="n">ureg0</span><span class="p">,</span><span class="w"> </span><span class="n">src</span><span class="p">,</span><span class="w"> </span><span class="n">count</span><span class="p">);</span>
<span class="w">        </span><span class="n">asc_storeunalign_postupdate</span><span class="p">(</span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="n">ureg1</span><span class="p">,</span><span class="w"> </span><span class="n">data_reg</span><span class="p">,</span><span class="w"> </span><span class="n">count</span><span class="p">);</span>
<span class="w">    </span><span class="p">}</span>
<span class="w">    </span><span class="c1">// 非对齐搬出后处理，只需在循环结束后调用一次。</span>
<span class="w">    </span><span class="n">asc_storeunalign_post_postupdate</span><span class="p">(</span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="n">ureg1</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">);</span>
<span class="p">}</span>
</code></pre></div><p>搬运步骤如下：</p><ol><li>图中①：循环开始前，<code>asc_loadunalign_pre</code>将源地址所在32字节块的数据缓存到<code>ureg0</code>，为首次非对齐搬入准备前置数据。</li><li>图中②：首次循环调用<code>asc_loadunalign_postupdate</code>，将<code>ureg0</code>中的前置数据与后续读取数据拼接为一个VL长度的<code>data_reg</code>，并更新<code>ureg0</code>和<code>src</code>。</li><li>图中③：首次调用<code>asc_storeunalign_postupdate</code>，将<code>data_reg</code>中可直接写入的主块数据写入UB，将尾块缓存到<code>ureg1</code>，并更新<code>dst</code>。</li><li>图中④：后续循环再次调用<code>asc_loadunalign_postupdate</code>，复用更新后的<code>ureg0</code>和<code>src</code>完成下一次搬入，并再次更新二者。</li><li>图中⑤：后续调用<code>asc_storeunalign_postupdate</code>，将<code>ureg1</code>中的前序尾块与本次<code>data_reg</code>中的主块数据拼接后写入UB，再将本次尾块更新到<code>ureg1</code>并更新<code>dst</code>。</li><li>图中⑥：循环结束后，<code>asc_storeunalign_post_postupdate</code>将<code>ureg1</code>中最后缓存的尾块写入UB，完成连续非对齐搬出。</li></ol><p>示例中<code>count</code>为每次搬运的元素个数。<code>src</code>和<code>dst</code>分别由搬入、搬出接口自动更新，循环内需要复用各自的非对齐寄存器。<code>count</code>不超过单个矢量数据寄存器可容纳的元素个数，且搬入、搬出地址范围必须位于实际可用UB空间内。</p><h3 id="b64数据类型的搬运">b64数据类型的搬运<a class="header-anchor" href="#b64数据类型的搬运">​</a></h3><p>以下接口支持b64数据类型。</p><p><strong>表7</strong> 支持b64数据类型的接口</p><table><thead><tr><th>支持的数据类型</th><th>接口</th></tr></thead><tbody><tr><td><code>int64_t</code>、<code>uint64_t</code></td><td><a href="asc_loadalign.html">asc_loadalign</a><br><a href="asc_loadalign_postupdate.html">asc_loadalign_postupdate</a></td></tr><tr><td><code>int64_t</code></td><td><a href="asc_load.html">asc_load</a><br><a href="asc_loadunalign_pre.html">asc_loadunalign_pre</a><br><a href="asc_loadunalign.html">asc_loadunalign</a><br><a href="asc_loadunalign_postupdate.html">asc_loadunalign_postupdate</a></td></tr></tbody></table><p>当<code>asc_loadalign</code>、<code>asc_loadunalign_pre</code>或<code>asc_loadunalign_postupdate</code>通过地址寄存器访问b64数据时，地址寄存器更新接口不支持b64模式，应使用<a href="../reg_addr_reg/asc_update_addr_reg.html">asc_update_addr_reg_b32</a>生成地址寄存器。一个b64元素占用两个b32寻址单元，因此各维偏移量以及<code>asc_loadunalign_postupdate</code>的<code>inc</code>应设置为期望b64元素偏移量的2倍。</p><p><code>asc_loadalign</code>和<code>asc_loadalign_postupdate</code>的非连续对齐搬入模式中，处理<code>int64_t</code>数据时，掩码创建接口不支持b64模式。应先使用<a href="../reg_mask/asc_create_mask.html">asc_create_mask_b32</a>创建b32掩码，再使用<a href="../reg_permute_sel/asc_unpack.html">asc_unpack_lower</a>将其展开为b64数据对应的掩码。展开后的掩码以连续8个bit为一组，仅每组最低位的bit有效，用于控制一个b64元素。</p><p>以下示例以<code>asc_loadalign</code>为例，展示b64掩码的构造方式以及地址寄存器偏移量的换算方法。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">vector_int64_t</span><span class="w"> </span><span class="n">src_reg</span><span class="p">;</span>
<span class="n">vector_bool</span><span class="w"> </span><span class="n">mask_b32</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc_create_mask_b32</span><span class="p">(</span><span class="n">PAT_ALL</span><span class="p">);</span>
<span class="n">vector_bool</span><span class="w"> </span><span class="n">mask_b64</span><span class="p">;</span>
<span class="n">asc_unpack_lower</span><span class="p">(</span><span class="n">mask_b64</span><span class="p">,</span><span class="w"> </span><span class="n">mask_b32</span><span class="p">);</span>
<span class="n">addr_reg</span><span class="w"> </span><span class="n">load_offset</span><span class="p">;</span>
<span class="n">addr_reg</span><span class="w"> </span><span class="n">store_offset</span><span class="p">;</span>
<span class="k">for</span><span class="w"> </span><span class="p">(</span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">repeatTimes</span><span class="p">;</span><span class="w"> </span><span class="o">++</span><span class="n">i</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="n">load_offset</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc_update_addr_reg_b32</span><span class="p">(</span><span class="n">elements_vl</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="mi">2</span><span class="p">);</span>
<span class="w">    </span><span class="c1">// 搬出到UB后数据类型为B32，偏移不需要*2</span>
<span class="w">    </span><span class="n">store_offset</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc_update_addr_reg_b32</span><span class="p">(</span><span class="n">elements_vl</span><span class="p">);</span>
<span class="w">    </span><span class="n">asc_loadalign</span><span class="p">(</span><span class="n">src_reg</span><span class="p">,</span><span class="w"> </span><span class="n">input</span><span class="p">,</span><span class="w"> </span><span class="n">load_offset</span><span class="p">);</span>
<span class="w">    </span><span class="n">asc_storealign_pack</span><span class="p">(</span><span class="n">output</span><span class="p">,</span><span class="w"> </span><span class="n">src_reg</span><span class="p">,</span><span class="w"> </span><span class="n">store_offset</span><span class="p">,</span><span class="w"> </span><span class="n">mask_b64</span><span class="p">);</span>
<span class="p">}</span>
</code></pre></div></article></div>`,1)])])}const f=s(o,[["render",_]]);export{m as __pageData,f as default};
